import assert from 'node:assert/strict';
import proj4 from 'proj4';
import { createMapCoordinateSystem } from '../modules/geo/map-coordinates.js';

const system = createMapCoordinateSystem(proj4);
const near = (actual, expected, tolerance, label) => {
    assert.ok(Math.abs(actual - expected) < tolerance, `${label}: ${actual} != ${expected}`);
};

// Published MGGT / WGS84 pairs, not values generated by our inverse function.
// https://www.mos.ru/upload/documents/files/5663/Alabyshevo.pdf, printed page 31.
for (const [east, north, lon, lat] of [
    [-21466.9946, 37232.5806, 37.154079379, 56.000927977],
    [-21499.1597, 37238.6554, 37.153563358, 56.000981086],
    [-21504.3291, 37934.5807, 37.153424450, 56.007231121],
]) {
    const geographic = system.modelToWgs84({ east, north });
    near(geographic.lon, lon, 2e-8, 'MGGT longitude');
    near(geographic.lat, lat, 2e-8, 'MGGT latitude');
    const model = system.wgs84ToModel({ lon, lat });
    near(model.east, east, 0.003, 'MGGT easting');
    near(model.north, north, 0.003, 'MGGT northing');
}

const modelCenter = { east: 2322.8049850463867, north: 9741.543739318848 };
const area = system.getMapArea(modelCenter);
// Independent PROJ 9 result for the same explicitly declared CRS.
near(area.wgs84Center.lon, 37.53516376284391, 2e-8, 'Model longitude');
near(area.wgs84Center.lat, 55.754497223512494, 2e-8, 'Model latitude');
assert.equal(area.radiusMeters, 500);
assert.equal(area.modelBounds.east - area.modelBounds.west, 1000);
assert.equal(area.modelBounds.north - area.modelBounds.south, 1000);
const sw = system.wgs84ToMercator({ lon: area.bounds.west, lat: area.bounds.south });
const ne = system.wgs84ToMercator({ lon: area.bounds.east, lat: area.bounds.north });
assert.ok(ne.x - sw.x > 1700, '500 ground metres must not become 500 Web Mercator metres');
assert.ok(ne.y - sw.y > 1700);
const northWest = system.tileBounds({ x: area.tiles.minX, y: area.tiles.minY, z: area.tiles.z });
const southEast = system.tileBounds({ x: area.tiles.maxX, y: area.tiles.maxY, z: area.tiles.z });
assert.ok(northWest.west <= area.bounds.west && northWest.north >= area.bounds.north);
assert.ok(southEast.east >= area.bounds.east && southEast.south <= area.bounds.south);
assert.deepEqual(system.wgs84ToTile({ lon: 139.7006793, lat: 35.6590699 }, 18), { z: 18, x: 232798, y: 103246 });
assert.deepEqual(system.wgs84ToTile({ lon: 180, lat: 85.0511287798066 }, 0), { z: 0, x: 0, y: 0 });
near(system.tileBounds({ z: 0, x: 0, y: 0 }).south, -85.0511287798066, 1e-10, 'World tile south');
assert.throws(() => system.modelToWgs84({ east: NaN, north: 1 }), /finite/);
assert.throws(() => system.wgs84ToModel({ lon: '37', lat: 55 }), /finite/);
assert.throws(() => system.wgs84ToMercator({ lon: 0, lat: 90 }), /domain/);
assert.throws(() => system.getMapArea(modelCenter, { radiusMeters: -1 }), /radius/);
assert.throws(() => system.getMapArea(modelCenter, { zoom: 99 }), /zoom/);
assert.throws(() => system.tileBounds({ z: 1, x: 2, y: 0 }), /indices/);
console.log('MGGT, WGS84, Web Mercator and XYZ coordinate checks passed.');

export async function runMapCoordinatesSmoke(browser, baseUrl) {
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', (error) => errors.push(error.message));
    try {
        await page.goto(`${baseUrl}/__smoke_blank`, { waitUntil: 'domcontentloaded' });
        const result = await page.evaluate(async () => {
            const THREE = await import('three');
            const { loadMapCoordinateSystem } = await import('/scripts/modules/geo/map-coordinates.js');
            const { createMapReferenceController } = await import('/scripts/modules/scene/map-reference.js');
            const { createParcelsGroupFromGeoJSON } = await import('/scripts/modules/parcels.js');
            const firstLoad = loadMapCoordinateSystem();
            const samePromise = firstLoad === loadMapCoordinateSystem();
            const system = await firstLoad;
            const world = new THREE.Group();
            const root = new THREE.Group();
            const mesh = new THREE.Mesh(new THREE.BoxGeometry(100, 300, 140), new THREE.MeshBasicMaterial());
            mesh.position.set(2322.8049850463867, 200, -9741.543739318848);
            root.add(mesh);
            world.add(root);
            const models = [{ obj: root }];
            let zUp = false;
            const config = { THREE, world, getModels: () => models, isZUp: () => zUp };
            const reference = createMapReferenceController(config);
            const original = await reference.getMapArea();
            world.position.set(-20000, 300, 8000);
            world.rotation.set(0.3, -0.6, 0.2);
            world.scale.setScalar(1.5);
            const rebased = await reference.getMapArea();
            const afterRebase = world.position.toArray();
            const transformedCorners = system.wgs84ToModel(original.wgs84Center);
            zUp = true;
            mesh.rotation.x = Math.PI / 2;
            mesh.position.set(2322.8049850463867, 9741.543739318848, 200);
            const zUpArea = await reference.getMapArea();
            let resolveSystem;
            const pendingReference = createMapReferenceController({ ...config,
                loadCoordinateSystem: () => new Promise((resolve) => { resolveSystem = resolve; }) });
            const pending = pendingReference.getMapArea();
            mesh.position.x += 1000;
            resolveSystem(system);
            const afterSwitch = await pending;
            const disposedReference = createMapReferenceController({ ...config,
                loadCoordinateSystem: () => new Promise((resolve) => { resolveSystem = resolve; }) });
            const disposedPending = disposedReference.getMapArea().catch((error) => error.message);
            disposedReference.dispose();
            resolveSystem(system);
            const disposedError = await disposedPending;
            const p = original.wgs84Center;
            const parcels = await createParcelsGroupFromGeoJSON({ type: 'FeatureCollection', features: [{
                type: 'Feature', properties: {}, geometry: { type: 'Polygon', coordinates: [[
                    [p.lon, p.lat], [p.lon + 0.0001, p.lat], [p.lon, p.lat + 0.0001], [p.lon, p.lat],
                ]] },
            }] }, { coordinateSystem: system, verticalIsZ: false });
            const parcelOrigin = parcels.userData.originMeters;
            parcels.traverse((object) => { object.geometry?.dispose(); object.material?.dispose(); });
            reference.dispose();
            pendingReference.dispose();
            root.remove(mesh);
            mesh.geometry.dispose();
            mesh.material.dispose();
            return { samePromise, original, rebased, afterRebase, transformedCorners, zUpArea,
                afterSwitch, disposedError, parcelOrigin, remainingChildren: world.children.length };
        });
        assert.equal(result.samePromise, true, 'Concurrent imports must share one engine');
        for (const value of [result.rebased, result.zUpArea]) {
            near(value.modelCenter.east, result.original.modelCenter.east, 1e-7, 'Rebase easting');
            near(value.modelCenter.north, result.original.modelCenter.north, 1e-7, 'Rebase northing');
            assert.deepEqual(value.tiles, result.original.tiles, 'Rebase/up axis must not change tile selection');
        }
        assert.deepEqual(result.afterRebase, [-20000, 300, 8000], 'Map lookup must not mutate world transform');
        near(result.afterSwitch.modelCenter.east, result.original.modelCenter.east + 1000, 1e-7, 'Pending room switch');
        assert.match(result.disposedError, /disposed/);
        near(result.parcelOrigin.x, result.original.modelCenter.east, 0.003, 'Parcel easting');
        near(result.parcelOrigin.y, result.original.modelCenter.north, 0.003, 'Parcel northing');
        assert.equal(result.remainingChildren, 1, 'Map lookup must not add scene layers');
        assert.deepEqual(errors, []);
    } finally {
        await page.close();
    }
}
